//! Named character references (spec 0004, child 0002, Tokenizer).
//!
//! The table in `table.rs` is the WHATWG list (2,231 entries), generated by
//! `tools/gen_entities.rs`. Names are sorted and keep their trailing `;`
//! when they have one, so one longest prefix search covers both forms.

mod table;

pub(crate) use table::ENTITIES;

/// The longest name, `;` included, a reference can have
/// (`CounterClockwiseContourIntegral;`).
pub(crate) const MAX_NAME: usize = 32;

/// The longest name in the table that `text` starts with, and its
/// replacement.
pub(crate) fn longest_match(text: &str) -> Option<(&'static str, &'static str)> {
    // Try each prefix from the longest down; every shortest name has two
    // characters (`gt`, `lt`). Names are ASCII, so a prefix that does not
    // end on a char boundary cannot be one.
    let longest = text.len().min(MAX_NAME);
    (2..=longest).rev().find_map(|len| {
        let prefix = text.get(..len)?;
        let index = ENTITIES
            .binary_search_by(|(name, _)| (*name).cmp(prefix))
            .ok()?;
        ENTITIES.get(index).copied()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_complete_and_sorted() {
        assert_eq!(ENTITIES.len(), 2231);
        assert!(ENTITIES.windows(2).all(|pair| pair[0].0 < pair[1].0));
        assert!(ENTITIES.iter().all(|(name, _)| name.len() <= MAX_NAME));
    }

    #[test]
    fn the_longest_name_wins() {
        assert_eq!(longest_match("amp;x"), Some(("amp;", "&")));
        assert_eq!(longest_match("ampx"), Some(("amp", "&")));
        assert_eq!(longest_match("notin;"), Some(("notin;", "\u{2209}")));
        assert_eq!(longest_match("notit;"), Some(("not", "\u{AC}")));
        assert_eq!(
            longest_match("NotEqualTilde;"),
            Some(("NotEqualTilde;", "\u{2242}\u{338}"))
        );
        assert_eq!(longest_match("zzz"), None);
        assert_eq!(longest_match("g\u{E9}"), None);
    }
}
